    [Theory]
    [MemberData(nameof(Cases))]
    public void ErrorTextMatchesPython(string text, string? message)
    {
        if (message is null)
        {
            PythonJsonReader.Parse(text);
            return;
        }
        Assert.Equal(message, Assert.ThrowsAny<JsonException>(() => PythonJsonReader.Parse(text)).Message);
    }

    private static string Nested(int levels, string inner) =>
        "{\"cls_token\": \"[CLS]\", \"x\": " + new string('[', levels) + inner + new string(']', levels) + "}";

    // Python loads this much nesting (RecursionError past 2997 on 3.12); a re-emitted tokenizer_config must too.
    [Theory]
    [InlineData(10)]
    [InlineData(65)]
    [InlineData(900)]
    [InlineData(2990)]
    public void DeepNestingSurvivesTheReEmission(int levels)
    {
        using var doc = PythonJsonReader.ParseDocument(Nested(levels, "1"), out _);
        Assert.Equal("[CLS]", doc.RootElement.GetProperty("cls_token").GetString());
        var depth = 0;
        var element = doc.RootElement.GetProperty("x");
        while (element.ValueKind == JsonValueKind.Array) { depth++; element = element[0]; }
        Assert.Equal(levels, depth);
    }

    [Fact]
    public void DeepNestingNeedsNoStackProportionalToItsDepth()
    {
        // 2990 levels on a 256 KB thread. Neither the parse nor the re-emission may recurse, because the
        // caller's stack is the one thing this port cannot ask anyone to make bigger. Before both walks became
        // iterative this test killed the test host outright ("Stack overflow ... Abort trap: 6") -- which is
        // the defect itself: .NET cannot catch a stack overflow, so a document CPython loads had no way to be
        // reported as an error either.
        var text = Nested(2990, "1");
        Exception? caught = null;
        var thread = new Thread(
            () =>
            {
                try
                {
                    using var doc = PythonJsonReader.ParseDocument(text, out _);
                    if (doc.RootElement.GetProperty("cls_token").GetString() != "[CLS]")
                        throw new InvalidOperationException("re-emitted payload lost a field");
                    var depth = 0;
                    var element = doc.RootElement.GetProperty("x");
                    while (element.ValueKind == JsonValueKind.Array) { depth++; element = element[0]; }
                    if (depth != 2990) throw new InvalidOperationException($"depth {depth} != 2990");
                }
                catch (Exception e) { caught = e; }
            },
            maxStackSize: 256 * 1024);
        thread.Start();
        thread.Join();
        Assert.Null(caught);
    }

    [Fact]
    public void NestingPastPythonsLimitIsRejected() =>
        Assert.ThrowsAny<JsonException>(() => PythonJsonReader.Parse(new string((char)91, 2998) + new string((char)93, 2998)));

    [Fact]
    public void ANestingAtPythonsLimitLoads() =>
        Assert.IsType<List<object?>>(PythonJsonReader.Parse(new string((char)91, 2997) + new string((char)93, 2997)));

    [Fact]
    public void AReadTokenFieldThatCannotSurviveReEmissionIsFlagged()
    {
        PythonJsonReader.ParseDocument("{\"cls_token\": NaN, \"sep_token\": \"a\", \"pad_token\": \"\\ud800\"}", out var tree);
        var fields = Assert.IsAssignableFrom<IReadOnlyDictionary<string, object?>>(tree);
        Assert.True(PythonJsonReader.IsAlteredByReEmission(fields["cls_token"]));
        Assert.False(PythonJsonReader.IsAlteredByReEmission(fields["sep_token"]));
        Assert.True(PythonJsonReader.IsAlteredByReEmission(fields["pad_token"]));
    }
}
